1	package cli
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"time"
11	
12		"gopkg.in/yaml.v3"
13	)
14	
15	// Managed-install manifests. A plugin installed from a remote repository
16	// gets a per-plugin home under the managed dir:
17	//
18	//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
19	//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
20	//
21	// The bin/ dir remains the only dispatch surface — pkg/ binaries are
22	// linked into bin/ via the same symlink→hardlink→copy fallback as local
23	// installs, so the kubectl-style resolver in plugin.go never changes.
24	//
25	// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
26	// and have no manifest; ListPluginManifests simply doesn't see them.
27	const (
28		pluginManagedPkgSubdir = "pkg"
29		pluginManifestFileName = "manifest.yml"
30	)
31	
32	// PluginManifest records how a managed plugin was installed. Settings
33	// configure behavior; manifests record facts. The dependency list is
34	// copied from the plugin's metadata at install time so reverse-dependency
35	// checks (remove guard, doctor) work offline.
36	type PluginManifest struct {
37		// Name is the bare plugin name ("run" for entire-run).
38		Name string `yaml:"name"`
39		// RepoURL is the full git URL the plugin was installed from.
40		RepoURL string `yaml:"repo_url"`
41		// Tag is the git tag that was installed (e.g. "v0.2.1").
42		Tag string `yaml:"tag"`
43		// Asset is the release asset filename the binary came from. Empty for
44		// raw-binary downloads where the asset name equals the binary name.
45		Asset string `yaml:"asset,omitempty"`
46		// SHA256 is the hex digest of the downloaded asset.
47		SHA256 string `yaml:"sha256,omitempty"`
48		// Pinned marks installs done with --pin; upgrade skips them.
49		Pinned bool `yaml:"pinned,omitempty"`
50		// InstalledAt is when the install (or last upgrade) completed.
51		InstalledAt time.Time `yaml:"installed_at,omitempty"`
52		// Requires is the dependency list from the plugin's entire-plugin.yml
53		// at the installed tag.
54		Requires []PluginRequirement `yaml:"requires,omitempty"`
55	}
56	
57	// PluginRequirement declares a dependency on another plugin. Shared between
58	// the author-side metadata file (entire-plugin.yml) and the install-side
59	// manifest so the two can never drift.
60	type PluginRequirement struct {
61		// Name is the bare plugin name of the dependency.
62		Name string `yaml:"name"`
63		// RepoURL is where to install the dependency from when it's missing.
64		// Optional when the dependency is resolvable through the index.
65		RepoURL string `yaml:"repo_url,omitempty"`
66		// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
67		// only — there is deliberately no range syntax.
68		MinVersion string `yaml:"min_version,omitempty"`
69	}
70	
71	// PluginMetadata is the author-side declaration committed at the root of a
72	// plugin repository as entire-plugin.yml. Everything is optional — a repo
73	// without the file installs fine; the name then derives from the repo URL.
74	type PluginMetadata struct {
75		// Name is the bare plugin name. When empty, derived from the repo URL
76		// basename (entire-run → run).
77		Name string `yaml:"name,omitempty"`
78		// Description is a one-line summary shown by info/search.
79		Description string `yaml:"description,omitempty"`
80		// DownloadURL overrides the per-forge release-asset URL convention.
81		// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
82		// When {asset} is present, candidate asset filenames are substituted;
83		// otherwise the expanded template is fetched as-is.
84		DownloadURL string `yaml:"download_url,omitempty"`
85		// Requires lists plugins this plugin needs at runtime.
86		Requires []PluginRequirement `yaml:"requires,omitempty"`
87	}
88	
89	// pluginMetadataFileName is the well-known path of the author-side metadata
90	// file at the root of a plugin repository.
91	const pluginMetadataFileName = "entire-plugin.yml"
92	
93	// ParsePluginMetadata decodes entire-plugin.yml content. Strict decoding:
94	// unknown keys are an error, surfacing author typos at install time rather
95	// than silently ignoring a misspelled "requires".
96	func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
97		var meta PluginMetadata
98		dec := yaml.NewDecoder(bytes.NewReader(data))
99		dec.KnownFields(true)
100		if err := dec.Decode(&meta); err != nil {
101			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
102		}
103		if meta.Name != "" {
104			if err := validatePluginName(meta.Name); err != nil {
105				return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
106			}
107		}
108		for _, req := range meta.Requires {
109			if err := validatePluginName(req.Name); err != nil {
110				return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
111			}
112		}
113		return &meta, nil
114	}
115	
116	// PluginPkgDir returns the per-plugin package directory for the given bare
117	// name. Not created — callers use EnsurePluginPkgDir when writing.
118	func PluginPkgDir(name string) (string, error) {
119		if err := validatePluginName(name); err != nil {
120			return "", err
121		}
122		parent, err := pluginParentDir()
123		if err != nil {
124			return "", err
125		}
126		return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
127	}
128	
129	// EnsurePluginPkgDir creates the package directory for name.
130	func EnsurePluginPkgDir(name string) (string, error) {
131		dir, err := PluginPkgDir(name)
132		if err != nil {
133			return "", err
134		}
135		if err := os.MkdirAll(dir, 0o750); err != nil {
136			return "", fmt.Errorf("create plugin pkg dir: %w", err)
137		}
138		return dir, nil
139	}
140	
141	// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
142	// the plugin has no manifest — local-dev installs and raw-PATH plugins.
143	func LoadPluginManifest(name string) (*PluginManifest, error) {
144		dir, err := PluginPkgDir(name)
145		if err != nil {
146			return nil, err
147		}
148		data, err := os.ReadFile(filepath.Join(dir, pluginManifestFileName)) //nolint:gosec // path is inside the managed pkg tree
149		if err != nil {
150			if errors.Is(err, os.ErrNotExist) {
151				return nil, nil //nolint:nilnil // no-manifest signal
152			}
153			return nil, fmt.Errorf("read plugin manifest: %w", err)
154		}
155		var m PluginManifest
156		if err := yaml.Unmarshal(data, &m); err != nil {
157			return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
158		}
159		return &m, nil
160	}
161	
162	// SavePluginManifest writes the manifest into the plugin's pkg dir.
163	func SavePluginManifest(m *PluginManifest) error {
164		dir, err := EnsurePluginPkgDir(m.Name)
165		if err != nil {
166			return err
167		}
168		data, err := yaml.Marshal(m)
169		if err != nil {
170			return fmt.Errorf("marshal plugin manifest: %w", err)
171		}
172		path := filepath.Join(dir, pluginManifestFileName)
173		if err := os.WriteFile(path, data, 0o644); err != nil { //nolint:gosec // manifest is non-secret provenance metadata
174			return fmt.Errorf("write plugin manifest: %w", err)
175		}
176		return nil
177	}
178	
179	// ListPluginManifests returns the manifests of every remote-installed
180	// plugin, sorted by name. Pkg entries without a readable manifest are
181	// skipped — a half-removed plugin shouldn't break listing.
182	func ListPluginManifests() ([]*PluginManifest, error) {
183		parent, err := pluginParentDir()
184		if err != nil {
185			return nil, err
186		}
187		entries, err := os.ReadDir(filepath.Join(parent, pluginManagedPkgSubdir))
188		if err != nil {
189			if errors.Is(err, os.ErrNotExist) {
190				return nil, nil
191			}
192			return nil, fmt.Errorf("read plugin pkg dir: %w", err)
193		}
194		var out []*PluginManifest
195		for _, e := range entries {
196			if !e.IsDir() {
197				continue
198			}
199			m, err := LoadPluginManifest(e.Name())
200			if err != nil || m == nil {
201				continue
202			}
203			out = append(out, m)
204		}
205		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
206		return out, nil
207	}
208	
209	// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
210	// Missing dir is not an error — local-dev installs never had one.
211	func RemovePluginPkg(name string) error {
212		dir, err := PluginPkgDir(name)
213		if err != nil {
214			return err
215		}
216		if err := os.RemoveAll(dir); err != nil {
217			return fmt.Errorf("remove plugin pkg dir: %w", err)
218		}
219		return nil
220	}
